package cli

import (
	"strings"

	"github.com/entireio/entire-brain/internal/providerdetail"
	"github.com/entireio/entire-brain/internal/tui"
)

const (
	// setupBrainBinaryName is this binary's own name: what a reader who runs it
	// directly types.
	setupBrainBinaryName = "entire-brain"
	// setupEntireBinaryName is the host CLI that dispatches this binary as an
	// external command, and setupBrainPluginVerb is the verb it dispatches on.
	setupEntireBinaryName = "entire"
	setupBrainPluginVerb  = "brain"
	// setupPluginCommand is the plugin spelling: what the reader types when they
	// reach this binary through the Entire CLI.
	setupPluginCommand = setupEntireBinaryName + " " + setupBrainPluginVerb
)

// setupCommandPrefix answers WHICH of the two spellings of this program the
// reader actually typed. The resolution lives in internal/providerdetail so
// that packages outside internal/cli -- the entity index, which must name the
// same re-run command the semantic index names -- can reach it; see
// providerdetail.SetupCommand for the signal and why it is the only one.
func setupCommandPrefix(lookup tui.EnvLookup) string {
	return providerdetail.SetupCommand(providerdetail.EnvLookup(lookup))
}

// setupBrainCommand is the guard every printer goes through, so that a caller
// that forgot to resolve a prefix prints the standalone name rather than a
// command starting with a space.
func setupBrainCommand(brainCmd string) string {
	if trimmed := strings.TrimSpace(brainCmd); trimmed != "" {
		return trimmed
	}
	return setupBrainBinaryName
}

// semanticIndexVerb is the command path that builds the semantic index, as
// cobra registers it: `index` hangs off `refresh`, not off the root.
//
// Twelve strings used to tell the reader to run "entire brain index" (quoted
// here rather than shown as a command, because it is not one and this package
// holds every printed command to resolving) -- a verb that has never existed — the binary answers `unknown command "index"`. The
// advice was unrunnable in both spellings, so every one of them was a dead end
// handed to a user whose index was already missing. The verb lives here, beside
// the prefix, so the two halves of a printed command cannot drift apart.
const semanticIndexVerb = "refresh index"

// brainInvocation renders a command the reader can actually type: the spelling
// of this program they reached (see setupCommandPrefix) followed by a verb path
// that cobra resolves. Every printed command goes through it rather than
// hardcoding one of the two binary names.
func brainInvocation(lookup tui.EnvLookup, verb string) string {
	command := setupBrainCommand(setupCommandPrefix(lookup))
	if verb = strings.TrimSpace(verb); verb != "" {
		command += " " + verb
	}
	return command
}

package cli

import (
	"errors"
	"fmt"
	"os/exec"
	"strings"
)

// host_cli.go names one condition: the host Entire CLI this plugin runs under
// is not installed on this machine.
//
// The brain is an Entire CLI plugin, but a built brain is a directory of JSON
// and SQLite that the README promises stays "fully readable and queryable with
// no `entire` on PATH". Readable it was; refreshable it was not. Session
// capture is the one source that reads THROUGH the host CLI, and when that
// subprocess could not be launched the failure travelled up as the raw
//
//	complete routed checkpoint discovery failed: list checkpoints: entire
//	[checkpoint explain --json --search-all]: exec: "entire": executable file
//	not found in $PATH
//
// — a Go error string naming neither the condition nor a way out.
//
// The distinction this file draws is the load-bearing one. A host CLI that is
// ABSENT is an environmental fact about the machine: nothing in the brain is
// broken, no repair applies to it, and it reads exactly the same on the first
// refresh and the hundredth. A host CLI that is PRESENT and whose export
// failed is a fault with a cause and a repair, and it must stay fatal — the
// alternative is answering real data loss with "unavailable, using seed
// baseline", which is the masking this codebase has already had to undo once
// (see discardManifestThisBuildCannotRewrite in refresh.go).

// hostCLIMissingCode prefixes the degraded message so a reader — and
// newSetupComponent's detail matching — keys on a code rather than prose.
const hostCLIMissingCode = "host_cli_missing"

// hostCLIMissing reports whether err is the host CLI failing to LAUNCH because
// the binary does not exist, as opposed to a command that ran and failed.
//
// The evidence is positive and structural, never a substring of the rendered
// message: exec.Command records LookPath's verdict as *exec.Error{Name, Err},
// and every other outcome — a nonzero exit, a parse failure, a timeout —
// arrives as some other type. errors.As walks the wrapping this package adds
// (runExecCommand, listRoutedCheckpoints, discoverCheckpoints), so the signal
// survives the chain intact. The Name check is what keeps a MISSING GIT, which
// produces the same exec.ErrNotFound from the same call site, from being
// reported as an absent Entire CLI.
//
// A binary named by an explicit path that does not exist (--entire-binary
// /nope/entire) is deliberately NOT covered: exec skips LookPath for a path
// with a separator, so there is no ErrNotFound to match, and an operator who
// named a binary by hand asked for that name to be honoured or refused.
func hostCLIMissing(err error, binary string) bool {
	if err == nil {
		return false
	}
	var execErr *exec.Error
	if !errors.As(err, &execErr) {
		return false
	}
	if !errors.Is(execErr.Err, exec.ErrNotFound) {
		return false
	}
	return execErr.Name == hostCLIBinaryName(binary)
}

// hostCLIBinaryName resolves the configured --entire-binary, falling back to
// the default the flag itself defaults to.
func hostCLIBinaryName(binary string) string {
	if trimmed := strings.TrimSpace(binary); trimmed != "" {
		return trimmed
	}
	return entireBinaryName
}

// hostCLIMissingExportError restates a session-export launch failure as a
// named condition with a remedy, in the shape `setup` already uses for the
// missing semantic provider:
//
//	<code>: <what needs the tool and why it could not be used>: <raw detail>
//	-- <the step that fixes it>
//
// The original error is wrapped, not replaced, so the raw text a bug report
// needs survives and hostCLIMissing still recognises the result.
func hostCLIMissingExportError(err error, binary string) error {
	name := hostCLIBinaryName(binary)
	return fmt.Errorf(
		"%s: session capture reads agent checkpoints through the Entire CLI and `%s` is not on PATH: %w"+
			" -- install the Entire CLI, then run `%s enable` in this repo;"+
			" every other brain source is built without it",
		hostCLIMissingCode, name, err, entireBinaryName)
}

// hostCLISemanticProviderAbsent reports that the semantic index cannot be built
// because its provider is reached THROUGH the host Entire CLI (`entire graph`)
// and that binary is not installed.
//
// Session capture is not the only stage that runs the host CLI, so fixing only
// the export moved the same fatal error one stage down the refresh: the export
// degraded and `semantic index: verifying provider failed` then aborted the run
// for the identical reason. This is the same environmental condition and it
// degrades the same way.
//
// The probe answers only the host-CLI-missing half. A host CLI that is
// PRESENT but has no graph plugin degrades the same way, but by error shape
// instead of probe: semanticDoctorFailureError types that class as
// errSemanticProviderAbsent and refresh forgives it. Graph is encouraged,
// never required — only a provider that is present and breaks stays fatal.
func hostCLISemanticProviderAbsent(graphBinary string) bool {
	return hostCLIBinaryName(graphBinary) == entireBinaryName && !hostCLIOnPath()
}

// hostCLIOnPath reports whether the host Entire CLI can be launched at all.
//
// This is a PROBE, not an inference from a failure: `status` uses it to decide
// whether to name the host CLI as the blocker in its verdict, and a verdict
// that guessed would be the same class of defect it exists to report.
// inspectSessionEndHook already asks exactly this question the same way.
func hostCLIOnPath() bool {
	_, err := exec.LookPath(entireBinaryName)
	return err == nil
}

package cli

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"
)

const (
	brainBriefPostIndexTermLimit   = 6
	brainBriefPostIndexPathLimit   = 64
	brainBriefPostIndexOutputLimit = 64 * 1024
	brainBriefPostIndexTimeout     = 500 * time.Millisecond
)

var (
	brainBriefFullCommitPattern     = regexp.MustCompile(`^(?:[0-9a-fA-F]{40}|[0-9a-fA-F]{64})$`)
	brainBriefLocatorTokenPattern   = regexp.MustCompile(`(?i)[\p{L}\p{N}]{3,}|v[0-9]{1,4}`)
	brainBriefVersionLocatorPattern = regexp.MustCompile(`^v[0-9]{1,4}$`)
	errBrainBriefPostIndexTruncated = errors.New("truncated NUL-delimited git output")
)

type brainBriefPostIndexCandidate struct {
	path      string
	score     int
	benchmark bool
}

// brainBriefPromotePostIndexFiles bridges one narrow stale-index blind spot:
// files committed after the semantic snapshot cannot appear in its symbol
// results, and a clean worktree has no live changed-file overlay. The bridge is
// intentionally brief-only and task-filtered. It never broadens Live.ChangedFiles
// (which is also the deletion/restoration trust boundary).
func brainBriefPromotePostIndexFiles(
	ctx context.Context,
	runner CommandRunner,
	status brainStatusReport,
	task string,
	report *brainBriefReport,
) {
	brainBriefPromotePostIndexFilesWithTimeout(ctx, runner, status, task, report, brainBriefPostIndexTimeout)
}

func brainBriefPromotePostIndexFilesWithTimeout(ctx context.Context, runner CommandRunner, status brainStatusReport, task string, report *brainBriefReport, timeout time.Duration) {
	if report == nil {
		return
	}
	editFiles, testFiles := brainBriefPostIndexFilesWithTimeout(ctx, runner, status, task, timeout)
	if len(editFiles) == 0 && len(testFiles) == 0 {
		return
	}
	report.LikelyEditFiles = brainBriefMergePrioritizedFiles(editFiles, report.LikelyEditFiles, 8)
	report.LikelyTestFiles = brainBriefMergePrioritizedFiles(testFiles, report.LikelyTestFiles, 6)
	report.LikelyFiles = brainBriefMergeLikelyFiles(report.LikelyEditFiles, report.LikelyTestFiles)
}

func brainBriefPostIndexFiles(ctx context.Context, runner CommandRunner, status brainStatusReport, task string) ([]string, []string) {
	return brainBriefPostIndexFilesWithTimeout(ctx, runner, status, task, brainBriefPostIndexTimeout)
}

// Keep the product latency budget separate from real-Git integration tests:
// process startup under Windows race instrumentation can exceed 500ms alone.
func brainBriefPostIndexFilesWithTimeout(ctx context.Context, runner CommandRunner, status brainStatusReport, task string, timeout time.Duration) ([]string, []string) {
	if runner == nil {
		return nil, nil
	}
	repoRoot, indexed, current, ok := brainBriefPostIndexRange(status)
	if !ok {
		return nil, nil
	}
	terms := brainBriefPostIndexLocatorTerms(task)
	if len(terms) < 2 {
		return nil, nil
	}

	boundedCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	if _, _, err := runner.Run(boundedCtx, repoRoot, "git", "merge-base", "--is-ancestor", indexed, current); err != nil {
		return nil, nil
	}
	paths, ok := brainBriefPostIndexDiffPaths(boundedCtx, cancel, runner, repoRoot, indexed, current, terms)
	if !ok {
		return nil, nil
	}

	repoFiles, ok := newBrainBriefRepoFileChecker(repoRoot)
	if !ok {
		return nil, nil
	}
	performanceIntent := brainBriefPerformanceIntent(task)
	candidates := make([]brainBriefPostIndexCandidate, 0, len(paths))
	seen := make(map[string]struct{}, len(paths))
	for _, path := range paths {
		clean, valid := cleanBrainBriefLikelyFile(path)
		if !valid || !repoFiles.exists(clean) {
			continue
		}
		if _, duplicate := seen[clean]; duplicate {
			continue
		}
		seen[clean] = struct{}{}
		hits := brainBriefPostIndexTermHits(clean, terms)
		benchmark := brainBriefBenchmarkPath(clean)
		score := hits
		if benchmark && !performanceIntent {
			score--
		}
		if score < 2 {
			continue
		}
		candidates = append(candidates, brainBriefPostIndexCandidate{
			path:      clean,
			score:     score,
			benchmark: benchmark,
		})
	}
	sort.Slice(candidates, func(i, j int) bool {
		if candidates[i].score != candidates[j].score {
			return candidates[i].score > candidates[j].score
		}
		if candidates[i].benchmark != candidates[j].benchmark {
			if performanceIntent {
				return candidates[i].benchmark
			}
			return !candidates[i].benchmark
		}
		return candidates[i].path < candidates[j].path
	})

	var editFiles, testFiles []string
	for _, candidate := range candidates {
		if brainBriefLikelyTestFile(candidate.path) {
			if len(testFiles) == 0 {
				testFiles = append(testFiles, candidate.path)
			}
			continue
		}
		if len(editFiles) == 0 {
			editFiles = append(editFiles, candidate.path)
		}
		if len(editFiles) == 1 && len(testFiles) == 1 {
			break
		}
	}
	return editFiles, testFiles
}

func brainBriefPostIndexRange(status brainStatusReport) (repoRoot, indexed, current string, ok bool) {
	if status.Semantic == nil || status.Semantic.Freshness == nil || status.Manifest == nil ||
		status.Manifest.Sources == nil || status.Manifest.Sources.Semantic == nil {
		return "", "", "", false
	}
	head, exists := status.Semantic.Freshness.Axes["head"]
	if !exists || head.State != "stale" {
		return "", "", "", false
	}
	indexed = strings.ToLower(strings.TrimSpace(head.Indexed))
	current = strings.ToLower(strings.TrimSpace(head.Current))
	liveHead := strings.ToLower(strings.TrimSpace(status.Live.Head))
	sourceCommit := strings.ToLower(strings.TrimSpace(status.Manifest.Sources.Semantic.Commit))
	if !brainBriefFullCommitPattern.MatchString(indexed) || !brainBriefFullCommitPattern.MatchString(current) ||
		len(indexed) != len(current) || indexed == current || liveHead != current || sourceCommit != indexed ||
		strings.TrimSpace(status.Repo.Root) == "" {
		return "", "", "", false
	}
	return status.Repo.Root, indexed, current, true
}

func brainBriefPostIndexLocatorTerms(task string) []string {
	type locatorToken struct {
		value      string
		start, end int
		version    bool
	}
	lowerTask := strings.ToLower(task)
	seen := map[string]struct{}{}
	tokens := make([]locatorToken, 0, brainBriefPostIndexTermLimit)
	for _, span := range brainBriefLocatorTokenPattern.FindAllStringIndex(lowerTask, -1) {
		match := lowerTask[span[0]:span[1]]
		if !brainBriefLiteralLocatorTerm(match) || brainBriefFileMatchTermStop(match) {
			continue
		}
		// Pathspec-looking task syntax is never passed through as magic, but it
		// is also poor locator material and must not displace real task terms.
		if brainBriefLocatorSyntaxField(lowerTask, span[0], span[1]) {
			continue
		}
		if _, duplicate := seen[match]; duplicate {
			continue
		}
		seen[match] = struct{}{}
		tokens = append(tokens, locatorToken{
			value:   match,
			start:   span[0],
			end:     span[1],
			version: brainBriefVersionLocatorPattern.MatchString(match),
		})
	}

	compoundNeighbor := map[string]bool{}
	for i, token := range tokens {
		if !token.version {
			continue
		}
		for _, neighborIndex := range []int{i - 1, i + 1} {
			if neighborIndex < 0 || neighborIndex >= len(tokens) || tokens[neighborIndex].version {
				continue
			}
			neighbor := tokens[neighborIndex]
			left, right := neighbor, token
			if left.start > right.start {
				left, right = right, left
			}
			if right.start == left.end+1 && brainBriefVersionCompoundSeparator(lowerTask[left.end]) {
				compoundNeighbor[neighbor.value] = true
			}
		}
	}

	versions := make([]string, 0, 1)
	compound := make([]string, 0, 1)
	ordinary := make([]string, 0, brainBriefPostIndexTermLimit)
	for _, token := range tokens {
		switch {
		case token.version:
			versions = append(versions, token.value)
		case compoundNeighbor[token.value]:
			compound = append(compound, token.value)
		default:
			ordinary = append(ordinary, token.value)
		}
	}
	// Short version locators are rare and precise. Keep them even when a long
	// task supplies more than six prose tokens, and keep their compound neighbor
	// (compact-v3) as one locator unit. When ordinary terms overflow the remaining
	// budget, retain anchors from both ends: task descriptions commonly put an
	// identifier near the start and the concrete failure near the end.
	terms := append([]string(nil), versions...)
	terms = append(terms, compound...)
	if len(terms) >= brainBriefPostIndexTermLimit {
		return terms[:brainBriefPostIndexTermLimit]
	}
	remaining := brainBriefPostIndexTermLimit - len(terms)
	if len(ordinary) <= remaining {
		return append(terms, ordinary...)
	}
	front := remaining / 2
	back := remaining - front
	terms = append(terms, ordinary[:front]...)
	terms = append(terms, ordinary[len(ordinary)-back:]...)
	return terms
}

func brainBriefLocatorSyntaxField(task string, start, end int) bool {
	fieldStart := start
	for fieldStart > 0 && !unicode.IsSpace(rune(task[fieldStart-1])) {
		fieldStart--
	}
	fieldEnd := end
	for fieldEnd < len(task) && !unicode.IsSpace(rune(task[fieldEnd])) {
		fieldEnd++
	}
	field := task[fieldStart:fieldEnd]
	return strings.Contains(field, ":(") || strings.ContainsAny(field, "[]!*?")
}

func brainBriefVersionCompoundSeparator(separator byte) bool {
	return separator == '-' || separator == '_'
}

func brainBriefLiteralLocatorTerm(term string) bool {
	if term == "" || len(term) > 64 || !utf8.ValidString(term) {
		return false
	}
	for _, r := range term {
		if !unicode.IsLetter(r) && !unicode.IsNumber(r) {
			return false
		}
	}
	return true
}

func brainBriefPostIndexDiffPaths(
	ctx context.Context,
	cancel context.CancelFunc,
	runner CommandRunner,
	repoRoot, indexed, current string,
	terms []string,
) ([]string, bool) {
	if len(terms) < 2 || len(terms) > brainBriefPostIndexTermLimit {
		return nil, false
	}
	for _, term := range terms {
		if !brainBriefLiteralLocatorTerm(term) {
			return nil, false
		}
	}
	streamer, ok := runner.(CommandStreamer)
	if !ok {
		return nil, false
	}
	args := []string{
		"-c", "core.quotepath=false", "diff", "--no-ext-diff", "--no-textconv",
		"--name-only", "-z", "--diff-filter=AMR", indexed, current, "--",
	}
	for _, term := range terms {
		// The term contains letters/numbers only. glob magic is fixed here, not
		// accepted from the task, so neither pathspec injection nor exclusions
		// can cross this boundary. **/ also matches files below any repository
		// directory; the top-level form covers root files explicitly.
		args = append(args,
			":(top,glob,icase)*"+term+"*",
			":(top,glob,icase)**/*"+term+"*",
		)
	}
	stream, err := streamer.Stream(ctx, repoRoot, "git", args...)
	if err != nil {
		return nil, false
	}
	defer stream.Close()

	scanner := bufio.NewScanner(stream.Stdout())
	scanner.Split(brainBriefScanNUL)
	scanner.Buffer(make([]byte, 1024), brainBriefPostIndexOutputLimit+1)
	paths := make([]string, 0, min(16, brainBriefPostIndexPathLimit))
	bytesRead := 0
	oversized := false
	for scanner.Scan() {
		value := scanner.Text()
		bytesRead += len(value) + 1
		if bytesRead > brainBriefPostIndexOutputLimit {
			oversized = true
			cancel()
			break
		}
		// OR pathspecs intentionally admit one-term names so two locator terms
		// can be spread across directories and the basename. Do not let that
		// one-term noise consume the candidate-count safety cap; the byte and
		// deadline caps above still bound all raw output.
		if brainBriefPostIndexTermHits(value, terms) < 2 {
			continue
		}
		if len(paths) >= brainBriefPostIndexPathLimit {
			oversized = true
			cancel()
			break
		}
		paths = append(paths, value)
	}
	if oversized {
		_ = stream.Close()
		_, _ = stream.Wait()
		return nil, false
	}
	if scanner.Err() != nil {
		cancel()
		_ = stream.Close()
		_, _ = stream.Wait()
		return nil, false
	}
	if _, err := stream.Wait(); err != nil || ctx.Err() != nil {
		return nil, false
	}
	return paths, true
}

func brainBriefScanNUL(data []byte, atEOF bool) (advance int, token []byte, err error) {
	if i := bytes.IndexByte(data, 0); i >= 0 {
		return i + 1, data[:i], nil
	}
	if atEOF {
		if len(data) == 0 {
			return 0, nil, nil
		}
		// A successful `git diff -z` always terminates every path with NUL.
		// Treat a truncated/malformed stream as an error via Scanner.
		return 0, nil, errBrainBriefPostIndexTruncated
	}
	return 0, nil, nil
}

func brainBriefPostIndexTermHits(path string, terms []string) int {
	normalized := strings.ToLower(filepath.ToSlash(path))
	base := filepath.Base(normalized)
	base = strings.TrimSuffix(base, filepath.Ext(base))
	segments := strings.FieldsFunc(normalized, func(r rune) bool {
		return r == '/' || r == '\\' || r == '.' || r == '-' || r == '_'
	})
	hits := 0
	baseHits := 0
	for _, term := range terms {
		if strings.Contains(base, term) {
			baseHits++
			hits++
			continue
		}
		for _, segment := range segments {
			if strings.Contains(segment, term) {
				hits++
				break
			}
		}
	}
	// A directory-only match is too broad on a long stale range. Require at
	// least one task locator in the basename, then allow a second locator from
	// a module/package directory (for example src/auth/token.go).
	if baseHits == 0 {
		return 0
	}
	return hits
}

func brainBriefBenchmarkPath(path string) bool {
	lower := strings.ToLower(filepath.ToSlash(path))
	base := filepath.Base(lower)
	return strings.Contains(base, "_bench") || strings.Contains(base, "benchmark") ||
		strings.Contains(lower, "/benchmarks/") || strings.HasPrefix(lower, "benchmarks/")
}

func brainBriefPerformanceIntent(task string) bool {
	for _, term := range brainBriefLocatorTokenPattern.FindAllString(strings.ToLower(task), -1) {
		switch {
		case strings.HasPrefix(term, "allocat"), strings.HasPrefix(term, "bench"),
			strings.HasPrefix(term, "optimiz"), term == "faster", term == "latency",
			term == "memory", term == "performance", term == "speed", term == "throughput":
			return true
		}
	}
	return false
}

	suffix := ""
	if statusCauseWidth > ellipsisWidth {
		limit = statusCauseWidth - ellipsisWidth
		suffix = statusCauseEllipsis
	}
	return string(runes[:limit]) + suffix
}

// statusHealth is the one-line verdict the short report ends on.
type statusHealth struct {
	Issues   int
	Warnings int
	Failed   []string
	Severity string
	// BrainMissing reports that this repository has no brain at all: the
	// manifest is absent and every source is unbuilt. It is a STATE, not a
	// problem count, which is why it cannot be folded into Issues — and why
	// the old verdict got it exactly backwards. Nothing built means nothing
	// broken, so every counter read zero and the first command a new user runs
	// answered "healthy" about a brain that does not exist.
	BrainMissing bool
	// SemanticMissing reports that a brain exists but its manifest declares no
	// semantic index, so `inspect code`, `query` and `brief` have nothing to
	// read. Freshness cannot see this either: with no semantic source there is
	// no freshness report, and brainStatusFreshnessSeverity returns "" — which
	// Healthy() used to accept as "fine".
	SemanticMissing bool
	// Cause names WHICH axis is not current, in the words `overview` uses. See
	// statusFreshnessCause.
	Cause string
	// HostCLIMissing reports that the Entire CLI this plugin runs under is not
	// installed. Sessions, the semantic index and the entity index are all built
	// THROUGH it, so while it is absent no refresh brings any of them back and
	// the verdict must say so rather than naming a command that cannot repair
	// what it just listed.
	HostCLIMissing bool
	// DirtyWorktree reports uncommitted changes in the working tree. Both stages
	// `refresh --agent none` would rebuild REFUSE that state by design — seed
	// with "dirty_worktree: refusing to seed uncommitted content without
	// --worktree", semantic with the same refusal to index it — so recommending
	// that command to a reader with a dirty tree is recommending an exit 1.
	DirtyWorktree bool
	// NoCapturedSessions reports the session export failing because Entire has
	// no readable checkpoints — the state every repository is in between
	// `entire enable` and its first finished agent session. `refresh --agent
	// none` re-runs that same export as its FIRST stage and aborts on the same
	// error, so naming it here hands the reader a remedy that reproduces the
	// condition it is supposed to clear. The remedy is a finished session, and
	// setupNoSessionsHint is where that sentence already lives.
	NoCapturedSessions bool
}

// statusRemedyRefresh is the deterministic rebuild. Named, because it is also
// the ONE remedy a dirty working tree invalidates, and the override has to be
// scoped to exactly it: a dirty tree does not change the right answer for a
// brain that was never built (`setup`) or for a corrupt store (`doctor`).
const statusRemedyRefresh = "refresh --agent none"

// buildStatusHealth counts everything a reader would call a problem.
func buildStatusHealth(report brainStatusReport) statusHealth {
	health := statusHealth{
		Issues:   len(report.Issues),
		Warnings: len(report.Warnings) + len(report.Live.Warnings),
		Severity: brainStatusFreshnessSeverity(report),
		// "absent" is inspectBrainManifestHealth's own word for a brain that
		// was never built (and for one just removed by `reset --force`).
		BrainMissing: report.Brain.ManifestState == "absent",
		Cause:        statusFreshnessCause(report),
	}
	// Only one of the two: "no brain" already implies "no semantic index", and
	// a verdict that said both would be reporting one fact twice.
	health.SemanticMissing = !health.BrainMissing && report.Semantic == nil
	if report.Onboarding != nil {
		health.HostCLIMissing = report.Onboarding.HostCLIMissing
		for _, component := range report.Onboarding.Components {
			if component.State == "failed" {
				health.Failed = append(health.Failed, component.Name)
				if setupIsNoReadableSessions(component.Detail) {
					health.NoCapturedSessions = true
				}
			}
		}
	}
	// The live worktree, not a freshness axis. The `dirty-unindexed` axis is one
	// SYMPTOM of a dirty tree and it was the obvious thing to key on, but it is
	// not the condition: after `refresh --worktree` the seed axis reads
	// `dirty-indexed` and freshness aggregates to "ok", while `refresh --agent
	// none` goes on refusing to reseed the same uncommitted content. Asking the
	// working tree directly covers both.
	health.DirtyWorktree = report.Live.Dirty
	return health
}

// statusFreshnessCause is the store-validity signal, and it is the SAME one
// `overview` prints: semanticStaleReport opens the semantic SQLite store and
// runs `PRAGMA integrity_check` on it, records the failure as
// store=unsafe (…), and freshnessSummary renders that axis. `overview` calls
// freshnessSummary; the short status report kept only the aggregate severity
// and threw the axes away, so one shredded SQLite file, a semantic index one
// commit behind, and a provider that was skipped all printed the same single
// word.
func statusFreshnessCause(report brainStatusReport) string {
	parts := make([]string, 0, 2)
	for _, freshness := range []*staleReport{
		semanticFreshnessOf(report),
		retrievalFreshnessOf(report),
	} {
		if freshness == nil || freshness.Severity == "ok" {
			continue
		}
		if summary := freshnessSummary(*freshness); summary != "" {
			parts = append(parts, summary)
		}
	}
	return truncateStatusCause(strings.Join(parts, "; "))
}

func semanticFreshnessOf(report brainStatusReport) *staleReport {
	if report.Semantic == nil {
		return nil
	}
	return report.Semantic.Freshness
}

func retrievalFreshnessOf(report brainStatusReport) *staleReport {
	if report.Retrieval == nil {
		return nil
	}
	return report.Retrieval.Freshness
}

// Total is how many distinct problems the verdict is reporting.
func (h statusHealth) Total() int { return h.Issues + h.Warnings + len(h.Failed) }

// Healthy reports whether the verdict is "nothing to do". A degraded or unsafe
// freshness severity counts as unhealthy even with no issues: a stale index is
// the failure most likely to make the brain quietly wrong. An absent brain and
// an absent semantic index are never healthy either — they are the two states
// in which every counter reads zero because nothing was ever built.
func (h statusHealth) Healthy() bool {
	if h.BrainMissing || h.SemanticMissing {
		return false
	}
	return h.Total() == 0 && (h.Severity == "" || h.Severity == "ok")
}

// repairCommand selects the subcommand that can repair or diagnose this state.
func (h statusHealth) repairCommand() string {
	switch {
	case h.BrainMissing:
		return "setup"
	case h.SemanticMissing, h.Severity != "" && h.Severity != "ok":
		// Deterministic and token-free: the index is rebuilt without asking an
		// agent for anything, which is what a stale, missing or corrupt index
		// needs.
		return statusRemedyRefresh
	default:
		return "doctor"
	}
}

// nextStepMessage gives one actionable next step. Missing brain and blocked
// repair take precedence; diagnosed faults outrank a missing-host advisory.
func (h statusHealth) nextStepMessage(brainCmd string) string {
	brainCmd = setupBrainCommand(brainCmd)
	command := "run `" + brainCmd + " " + h.repairCommand() + "`"
	switch {
	case h.BrainMissing:
		return command
	case h.DirtyWorktree && h.repairCommand() == statusRemedyRefresh:
		// The ONE remedy resolver for a dirty tree. Line() prints h.Cause
		// directly underneath this, and the cause used to carry a SECOND,
		// contradictory remedy of its own ("refresh with --worktree to include
		// current changes"). Causes state causes; this resolver owns the
		// remedy, and it names both ways out so neither has to be discovered
		// elsewhere.
		return setupDirtyWorktreeHint(brainCmd)
	case h.NoCapturedSessions && h.repairCommand() == statusRemedyRefresh:
		// Same shape as the dirty-tree override and scoped the same way: the
		// ONE remedy a failed session export invalidates is the one whose first
		// stage IS that export.
		return setupNoSessionsHint(brainCmd)
	case h.Issues > 0 || h.Severity != "" && h.Severity != "ok":
		return command
	case h.HostCLIMissing && len(h.Failed) > 0:
		return "`" + entireBinaryName + "` is not on PATH; install the Entire CLI, then run `" + brainCmd + " setup`"
	default:
		return command
	}
}

// Line renders the verdict.
func (h statusHealth) Line(render *tui.Renderer, brainCmd string) string {
	brainCmd = setupBrainCommand(brainCmd)
	if h.Healthy() {
		return render.Mark(tui.MarkDone) + " " + render.PhasePaint(tui.PhaseDone, "healthy")
	}
	parts := make([]string, 0, 6)
	if h.BrainMissing {
		parts = append(parts, "no brain for this repo yet")
	}
	if h.SemanticMissing {
		parts = append(parts, "no semantic index")
	}
	if len(h.Failed) > 0 {
		parts = append(parts, fmt.Sprintf("%s failed", strings.Join(h.Failed, ", ")))
	}
	if h.Issues > 0 {
		parts = append(parts, fmt.Sprintf("%d %s", h.Issues, plural(h.Issues, "issue")))
	}
	if h.Warnings > 0 {
		parts = append(parts, fmt.Sprintf("%d %s", h.Warnings, plural(h.Warnings, "warning")))
	}
	if h.Severity != "" && h.Severity != "ok" {
		parts = append(parts, "freshness "+h.Severity)
	}
	phase := tui.PhaseSkipped
	mark := tui.MarkSkipped
	if len(h.Failed) > 0 || h.Severity == "unsafe" {
		phase = tui.PhaseFailed
		mark = tui.MarkFailed
	}
	line := render.Mark(mark) + " " + render.PhasePaint(phase, strings.Join(parts, ", ")) +
		render.Dim(" "+render.Dash()+" "+h.nextStepMessage(brainCmd))
	if h.Cause != "" {
		line += "\n  " + render.Dim(h.Cause)
	}
	return line
}

func plural(n int, word string) string {
	if n == 1 {
		return word
	}
	return word + "s"
}

// statusFactsIdentity renders the fact count on the identity line. A bare
// "5 facts" is the manifest's CLAIM, and printing it unqualified is how a
// brain that had lost a fact still said 5 while recall produced 4. When the
// cross-check fails, both numbers are shown so the claim can never be mistaken
// for an observation.
func statusFactsIdentity(f *brainStatusFacts) string {
	if f.Integrity == nil || f.Integrity.OK() {
		return fmt.Sprintf("memories: %d", f.Facts)
	}
	// A store that would not parse yielded no count at all, so "0 readable"
	// would be a measurement nobody took. Say what is true: it could not be
	// read.
	if f.Integrity.Mode == factStoreDefectUnreadable {
		return fmt.Sprintf("memories: %d declared, store unreadable", f.Facts)
	}
	return fmt.Sprintf("memories: %d declared, %d readable", f.Facts, f.Integrity.Readable)
}

