		_ = f.Close()
		if !isLockBusy(err) {
			return nil, fmt.Errorf("lock file: %w", err)
		}
		if timeout <= 0 || time.Now().Add(fileLockRetryInterval).After(deadline) {
			return nil, fmt.Errorf("%s: timed out acquiring lock at %s", code, path)
		}
		time.Sleep(fileLockRetryInterval)
